const fs = require("fs");
const path = require("path");
const root = process.cwd();

function fail(msg) { console.error("✖ " + msg); process.exit(1); }
if (!fs.existsSync(path.join(root, "package.json"))) fail("Run this from your project root.");

const IMAGES = {
  "gele-blue-asooke-1.jpg": "",
  "gele-blue-asooke-2.jpg": "",
  "gele-peach-1.jpg": "",
  "gele-peach-2.jpg": "",
  "gele-pink-beaded-1.jpg": "",
  "gele-pink-beaded-2.jpg": "",
  "gele-pink-beaded-3.jpg": "",
  "gele-pink-dramatic-1.jpg": "",
  "gele-pink-dramatic-2.jpg": "",
  "gele-silver-editorial-1.jpg": "",
  "gele-silver-editorial-2.jpg": "",
  "gele-silver-editorial-3.jpg": "",
  "gele-silver-editorial-4.jpg": "",
  "gele-silver-editorial-5.jpg": "",
  "gele-white-beaded-1.jpg": "",
  "gele-white-beaded-2.jpg": "",
};

const imagesDir = path.join(root, "public", "images");
fs.mkdirSync(imagesDir, { recursive: true });
for (const [name, b64] of Object.entries(IMAGES)) {
  fs.writeFileSync(path.join(imagesDir, name), Buffer.from(b64, "base64"));
  console.log("✓ wrote public/images/" + name);
}

